#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
// Kernel: tiled GEMM C = A * B
// A: (M,K) row-major, B: (K,N) row-major, C: (M,N) row-major
template <class TA, class TB, class TC>
__global__ static void __launch_bounds__(512)
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, cute::Stride<int,int> dA,
            TB const* B, cute::Stride<int,int> dB,
            TC      * C, cute::Stride<int,int> dC)
{
  using namespace cute;
  // Larger CTA tile: 128x128 to increase operand reuse and halve B traffic vs 128x64.
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 16;
  constexpr int LDB = BN + 4;
  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);
  int lda = get<0>(dA);
  int ldb = get<1>(dB);
  int ldc = get<0>(dC);
  alignas(16) __shared__ TA smemA[2][BM * BK];
  alignas(16) __shared__ TB smemB[2][BK * LDB];
  int tid = threadIdx.x;
  int bm = blockIdx.x * BM;
  int bn = blockIdx.y * BN;
  // A tile: 128x16 floats = 512 float4, exactly one per thread.
  int a_row = tid >> 2;
  int a_col = (tid & 3) * 4;
  // B tile: 16x128 floats = 512 float4, exactly one per thread.
  int b_row = tid >> 5;
  int b_col = (tid & 31) * 4;
  const float4* gA0 = reinterpret_cast<const float4*>(A + (bm + a_row) * lda + a_col);
  const float4* gB = reinterpret_cast<const float4*>(B + b_row * ldb + bn + b_col);
  auto load_tile = [&](int kt, int stage) {
    float4* sA0 = reinterpret_cast<float4*>(&smemA[stage][a_row * BK + a_col]);
    __pipeline_memcpy_async(sA0, gA0 + kt * (BK / 4), 16);
    float4* sB = reinterpret_cast<float4*>(&smemB[stage][b_row * LDB + b_col]);
    __pipeline_memcpy_async(sB, gB + kt * (BK * ldb / 4), 16);
    __pipeline_commit();
  };
  // 16 warps as 4x4. Warp tile 32x32, thread tile 4x8.
  int warp = tid >> 5;
  int lane = tid & 31;
  int warp_m = warp >> 2;
  int warp_n = warp & 3;
  int tm = lane >> 2;
  int tn = lane & 3;
  int m0 = warp_m * 32 + tm * 4;
  int n0 = warp_n * 32 + tn * 8;
  float acc[4][8];
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    #pragma unroll
    for (int j = 0; j < 8; ++j) acc[i][j] = 0.0f;
  }
  int k_tiles = K / BK;
  load_tile(0, 0);
  for (int kt = 0; kt < k_tiles; ++kt) {
    int stage = kt & 1;
    bool has_next = (kt + 1 < k_tiles);
    if (has_next) load_tile(kt + 1, 1 - stage);
    __pipeline_wait_prior(has_next ? 1 : 0);
    __syncthreads();
    const float* sA = &smemA[stage][0];
    const float* sB = &smemB[stage][0];
    #pragma unroll
    for (int kk = 0; kk < BK; kk += 4) {
      float4 b_lo[4];
      float4 b_hi[4];
      #pragma unroll
      for (int r = 0; r < 4; ++r) {
        const float* brow = &sB[(kk + r) * LDB + n0];
        b_lo[r] = *reinterpret_cast<const float4*>(brow);
        b_hi[r] = *reinterpret_cast<const float4*>(brow + 4);
      }
      #pragma unroll
      for (int i = 0; i < 4; ++i) {
        float4 a = *reinterpret_cast<const float4*>(&sA[(m0 + i) * BK + kk]);
        float av[4] = {a.x, a.y, a.z, a.w};
        #pragma unroll
        for (int r = 0; r < 4; ++r) {
          acc[i][0] += av[r] * (&b_lo[r].x)[0];
          acc[i][1] += av[r] * (&b_lo[r].x)[1];
          acc[i][2] += av[r] * (&b_lo[r].x)[2];
          acc[i][3] += av[r] * (&b_lo[r].x)[3];
          acc[i][4] += av[r] * (&b_hi[r].x)[0];
          acc[i][5] += av[r] * (&b_hi[r].x)[1];
          acc[i][6] += av[r] * (&b_hi[r].x)[2];
          acc[i][7] += av[r] * (&b_hi[r].x)[3];
        }
      }
    }
    __syncthreads();
  }
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    float4* out = reinterpret_cast<float4*>(C + (bm + m0 + i) * ldc + bn + n0);
    out[0] = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
    out[1] = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
  }
}
// Host wrapper
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda());
  TORCH_CHECK(A.dim()==2 && B.dim()==2);
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat);
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K);
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 16 == 0);
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());
  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();
  auto dA = make_stride(K, 1);
  auto dB = make_stride(1, N);
  auto dC = make_stride(N, 1);
  auto shape_MNK = make_shape(M, N, K);
